        assert_eq!(
            store
                .pending_native_steers(&session.id, "turn-1")
                .unwrap()
                .len(),
            1
        );
        // Simulate a crash after the accepted marker but before cleanup.
        let mut reopened = AgentsWindow::with_data_root(data_root.clone());
